=== FILE: tb/tb_mac8.v ===
// Self-checking scoreboard testbench for mac8.
// The reference model below is written from interface_spec.md, sections 2.1-2.3,
// and is independent of the RTL: priority reset > clear > accumulate > hold;
// unsigned 8x8 product added to a 24-bit total; saturate to 0xFFFFFF when the sum
// would be more than 0xFFFFFF; sticky flag until clear or reset.
`timescale 1ns / 1ps
module tb_mac8;
    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg        clr   = 1'b0;
    reg        en    = 1'b0;
    reg  [7:0] a     = 8'd0;
    reg  [7:0] b     = 8'd0;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk(clk), .rst_n(rst_n), .clr(clr), .en(en),
        .a(a), .b(b), .acc(acc), .sat(sat)
    );

    always #5 clk = ~clk;

    // ------------------------------------------------------------------
    // Scoreboard state
    // ------------------------------------------------------------------
    reg         model_valid = 1'b0;   // model state is known only after a reset edge
    reg  [23:0] exp_acc     = 24'd0;
    reg         exp_sat     = 1'b0;
    reg  [23:0] prev_acc    = 24'd0;
    reg         prev_sat    = 1'b0;

    integer pass_count       = 0;
    integer fail_count       = 0;
    integer mismatches_shown = 0;
    integer cycle_no         = 0;

    // corner counters
    integer n_sat_event      = 0;  // an add that saturated
    integer n_exact_max      = 0;  // total reached exactly 0xFFFFFF without saturating
    integer n_sticky_hold    = 0;  // flag set, edge that must keep it without new saturation
    integer n_clr_with_en    = 0;  // clear offered together with an accumulate
    integer n_clr_while_sat  = 0;  // clear while the flag is set
    integer n_rst_with_en    = 0;  // reset offered together with an accumulate
    integer n_hold           = 0;  // en low, clr low, rst_n high

    reg [8*128-1:0] nonce;
    reg [31:0]      rng;
    reg [31:0]      r1;
    reg [31:0]      r2;
    integer         i;
    integer         got;

    // ------------------------------------------------------------------
    // Reference model: one rising edge, from the specification
    // ------------------------------------------------------------------
    task model_step;
        input       r_n;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        reg   [31:0] product;
        reg   [31:0] total;
        begin
            if (r_n == 1'b0) begin                       // MAC-RESET
                if (e) n_rst_with_en = n_rst_with_en + 1;
                exp_acc     = 24'd0;
                exp_sat     = 1'b0;
                model_valid = 1'b1;
            end else if (!model_valid) begin
                // state unknown before the first reset: nothing to predict
            end else if (c) begin                         // MAC-CLEAR (wins over en)
                if (e)       n_clr_with_en   = n_clr_with_en + 1;
                if (exp_sat) n_clr_while_sat = n_clr_while_sat + 1;
                exp_acc = 24'd0;
                exp_sat = 1'b0;
            end else if (e) begin                         // MAC-ACC
                product = {24'd0, ia} * {24'd0, ib};      // unsigned operands
                total   = {8'd0, exp_acc} + product;
                if (total > 32'h00FFFFFF) begin           // MAC-SAT
                    n_sat_event = n_sat_event + 1;
                    exp_acc = 24'hFFFFFF;
                    exp_sat = 1'b1;
                end else begin
                    if (exp_sat) n_sticky_hold = n_sticky_hold + 1;   // MAC-STICKY
                    else if (total == 32'h00FFFFFF) n_exact_max = n_exact_max + 1;
                    exp_acc = total[23:0];
                end
            end else begin                                // MAC-HOLD
                n_hold = n_hold + 1;
                if (exp_sat) n_sticky_hold = n_sticky_hold + 1;
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Compare every output after the edge
    // ------------------------------------------------------------------
    task check_outputs;
        input       r_n;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            if (model_valid) begin
                if ((acc !== exp_acc) || (sat !== exp_sat)) begin
                    fail_count = fail_count + 1;
                    if (mismatches_shown < 10) begin
                        $display("MISMATCH cycle %0d t=%0t: rst_n=%b clr=%b en=%b a=0x%02h b=0x%02h prev(acc=0x%06h sat=%b) | DUT acc=0x%06h sat=%b | model acc=0x%06h sat=%b",
                                 cycle_no, $time, r_n, c, e, ia, ib, prev_acc, prev_sat,
                                 acc, sat, exp_acc, exp_sat);
                    end
                    mismatches_shown = mismatches_shown + 1;
                end else begin
                    pass_count = pass_count + 1;
                end
            end
        end
    endtask

    // Drive one cycle: inputs at the falling edge, model at the rising edge,
    // compare 1 ns after it.
    task drive;
        input       r_n;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            @(negedge clk);
            rst_n = r_n; clr = c; en = e; a = ia; b = ib;
            @(posedge clk);
            prev_acc = exp_acc;
            prev_sat = exp_sat;
            model_step(r_n, c, e, ia, ib);
            #1;
            cycle_no = cycle_no + 1;
            check_outputs(r_n, c, e, ia, ib);
        end
    endtask

    task do_acc;
        input [7:0] ia;
        input [7:0] ib;
        begin
            drive(1'b1, 1'b0, 1'b1, ia, ib);
        end
    endtask

    task do_hold;
        input [7:0] ia;
        input [7:0] ib;
        begin
            drive(1'b1, 1'b0, 1'b0, ia, ib);
        end
    endtask

    task do_clear;
        begin
            drive(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);
        end
    endtask

    task rand_step;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task corner_required;
        input integer count;
        input [8*24-1:0] name;
        begin
            if (count == 0) begin
                fail_count = fail_count + 1;
                $display("CORNER NOT REACHED: %0s", name);
            end
        end
    endtask

    task print_verdict;
        integer k;
        reg [7:0] ch;
        begin
            $write("NIRMAAN-SIM ");
            for (k = 127; k >= 0; k = k - 1) begin
                ch = nonce[k*8 +: 8];
                if (ch != 8'd0) $write("%c", ch);
            end
            $write(" %0d passed, %0d failed\n", pass_count, fail_count);
        end
    endtask

    // ------------------------------------------------------------------
    // Stimulus
    // ------------------------------------------------------------------
    initial begin
        nonce = 0;
        got = $value$plusargs("nonce=%s", nonce);
        if (got == 0) got = $value$plusargs("NIRMAAN_NONCE=%s", nonce);
        if (got == 0) got = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got == 0) got = $value$plusargs("NONCE=%s", nonce);
        if (got == 0) begin
            fail_count = fail_count + 1;
            $display("ERROR: no nonce plusarg found");
        end

        // D1 reset wins over an offered accumulate, and over clr
        repeat (3) drive(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);
        drive(1'b0, 1'b0, 1'b0, 8'h00, 8'h00);

        // D2 hold from zero with busy operands
        repeat (3) do_hold(8'h12, 8'h34);

        // D3 basic accumulate, unsigned operands
        do_acc(8'd3,  8'd4);    // 12
        do_acc(8'hFF, 8'h01);   // +255 (signed reading would give -1)
        do_acc(8'h80, 8'h02);   // +256
        do_acc(8'hFF, 8'hFF);   // +65025
        do_acc(8'h00, 8'hFF);   // +0
        do_acc(8'hFF, 8'h00);   // +0
        do_acc(8'h7F, 8'h81);   // mixed MSBs

        // D4 hold with non-zero total
        repeat (4) do_hold(8'hFF, 8'hFF);

        // D5 clear wins over accumulate; D5b clear while idle
        drive(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        do_acc(8'd5, 8'd5);
        drive(1'b1, 1'b1, 1'b0, 8'hAA, 8'h55);

        // D6 reset in the middle of accumulating
        do_acc(8'd10, 8'd10);
        do_acc(8'd20, 8'd20);
        drive(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        do_acc(8'd1, 8'd1);

        // D7 reach exactly 0xFFFFFF without saturating, then saturate by +1
        do_clear;
        repeat (258) do_acc(8'hFF, 8'hFF);   // 16776450
        do_acc(8'hFF, 8'h03);                // +765 -> 0xFFFFFF, sat stays 0
        do_acc(8'h00, 8'h00);                // +0 at the limit, no saturation
        do_hold(8'h01, 8'h01);
        do_acc(8'h01, 8'h01);                // would be 0x1000000 -> saturate

        // D8 sticky flag through holds, zero adds and further adds
        repeat (3) do_hold(8'h00, 8'h00);
        repeat (3) do_acc(8'h00, 8'h00);
        do_acc(8'hFF, 8'hFF);
        do_acc(8'h01, 8'h00);
        repeat (2) do_hold(8'hFF, 8'hFF);

        // D9 clear drops the flag; small adds keep it 0
        do_clear;
        do_acc(8'd2, 8'd3);
        repeat (2) do_hold(8'd0, 8'd0);

        // D10 overshoot by a full product, then reset clears total and flag
        repeat (262) do_acc(8'hFF, 8'hFF);
        drive(1'b0, 1'b0, 1'b0, 8'h00, 8'h00);
        do_acc(8'd7, 8'd9);

        // D11 clear while saturated, with an accumulate offered at the same edge
        repeat (262) do_acc(8'hFF, 8'hFF);
        drive(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        do_acc(8'd1, 8'd2);

        // D12 reset and clear together while saturated
        repeat (262) do_acc(8'hFE, 8'hFF);
        drive(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);
        do_acc(8'd3, 8'd3);

        // Random phase A: frequent clear/reset mixed with accumulate
        rng = 32'hC0FFEE01;
        for (i = 0; i < 2000; i = i + 1) begin
            rand_step; r1 = rng;
            rand_step; r2 = rng;
            drive((r1[5:0]  != 6'd0),    // reset about 1/64
                  (r1[9:6]  == 4'd0),    // clear about 1/16
                  r1[10],                // en about 1/2
                  r2[7:0], r2[15:8]);
        end

        // Random phase B: rare clears, biased large operands, reaches saturation
        for (i = 0; i < 6000; i = i + 1) begin
            rand_step; r1 = rng;
            rand_step; r2 = rng;
            drive((r1[10:0]  != 11'd0),   // reset about 1/2048
                  (r1[20:11] == 10'd0),   // clear about 1/1024
                  (r1[22:21] != 2'd0),    // en about 3/4
                  r2[16] ? (8'hFF - {5'd0, r2[2:0]})  : r2[7:0],
                  r2[17] ? (8'hFF - {5'd0, r2[10:8]}) : r2[15:8]);
        end

        // Corners the run must have reached, or the clean pass says nothing about them
        corner_required(n_sat_event,     "saturation");
        corner_required(n_exact_max,     "exact 0xFFFFFF no sat");
        corner_required(n_sticky_hold,   "sticky hold");
        corner_required(n_clr_with_en,   "clear with accumulate");
        corner_required(n_clr_while_sat, "clear while saturated");
        corner_required(n_rst_with_en,   "reset with accumulate");
        corner_required(n_hold,          "hold");

        $display("corners: sat=%0d exact_max=%0d sticky_hold=%0d clr_with_en=%0d clr_while_sat=%0d rst_with_en=%0d hold=%0d cycles=%0d mismatches=%0d",
                 n_sat_event, n_exact_max, n_sticky_hold, n_clr_with_en,
                 n_clr_while_sat, n_rst_with_en, n_hold, cycle_no, mismatches_shown);

        print_verdict;
        $finish;
    end
endmodule
=== END FILE ===
